def register_source_figures(add, root):
    # Şekiller kalıcı soru kimliğine bağlanır; yeni bir sayı tahmin edilmez.
    for name, markup in SVG.items():
        add(name, [], markup)
    active = set()
    for path in (root / 'data').glob('*.json'):
        for q in json.loads(path.read_text()).get('questions', []):
            if q.get('needs_figure'):
                active.add(q['id'])
    refs = {'65009': 'met_low_motion_12oct2026'}
    for path in (root / 'data/kaynaklar/decisions').glob('*.json'):
        doc = json.loads(path.read_text())
        for c in doc.get('candidates', []):
            if not c.get('needs_figure'):
                continue
            code = c['section'][:3]
            ledger_path = root / f'data/kaynaklar/idler_{code}.json'
            if not ledger_path.exists():
                continue
            qid = json.loads(ledger_path.read_text())['anahtarlar'].get(c['key'])
            if qid in active:
                name = Path(c['figure_name']).stem
                if str(qid) in refs and refs[str(qid)] != name:
                    raise ValueError(f'Çelişen çizim eşlemesi: {qid}')
                refs[str(qid)] = name
    for qid, name in refs.items():
        if int(qid) in active:
            if name not in SVG:
                raise ValueError(f'Ek çizimin üretim kaynağı eksik: {name}')
            add(name, [int(qid)], SVG[name])
